"""Small, curated lessons. Each part has its own explanation and two checks.

Question tuples contain: prompt, correct choice, distractor. Choices are shuffled
when presented; the correct choice is kept on the server.
"""

def part(title, explanation, simpler, example, *questions):
    return dict(title=title, explanation=explanation, simpler=simpler,
                example=example, questions=questions)


